import{_ as e,V as a,W as r,a0 as t}from"./framework-9a29aaa0.js";const s={},i=t('<ul><li><a href="#vmware-ft">VMware-FT</a><ul><li><a href="#%E6%91%98%E8%A6%81">摘要</a></li></ul></li></ul><h1 id="vmware-ft" tabindex="-1"><a class="header-anchor" href="#vmware-ft" aria-hidden="true">#</a> VMware-FT</h1><h2 id="摘要" tabindex="-1"><a class="header-anchor" href="#摘要" aria-hidden="true">#</a> 摘要</h2><p>我们已经实现了一个商业企业级系统，用于提供容错虚拟机，该系统基于通过在另一台服务器上的备份虚拟机复制主虚拟机（VM）的执行这一方法。我们在 VMware vSphere 4.0 中设计了一个完整的系统，该系统易于使用，可在商用服务器上运行，并且通常会使实际应用程序的性能降低不到 10%。此外，对于一些实际应用程序，使主虚拟机和辅助虚拟机同步执行所需的数据带宽小于 20 Mbit/s，这使得在更长距离上实现容错成为可能。一个易于使用的商业系统，在故障后自动恢复冗余，除了复制虚拟机执行之外还需要许多额外的组件。我们已经设计并实现了这些额外的组件，并解决了在支持运行企业应用程序的虚拟机时遇到的许多实际问题。在本文中，我们描述了我们的基本设计，讨论了替代设计选择和许多实现细节，并提供了微基准测试和实际应用程序的性能结果。</p>',4),l=[i];function n(c,h){return a(),r("div",null,l)}const d=e(s,[["render",n],["__file","lesson4-vmwareFT.html.vue"]]);export{d as default};
